"use client";

import React, { useState, useMemo } from "react";
import timetableData from "@/timetable.json";
import {
  Calendar,
  Clock,
  MapPin,
  BookOpen,
  GraduationCap,
  Sparkles,
  Layers,
  FlaskConical,
  Coffee,
  CheckCircle2,
  ChevronRight,
  Filter,
  Flame,
} from "lucide-react";

interface ScheduleItem {
  id: string;
  day: string;
  category: string;
  room: string;
  time_slot: string;
  start_time: string;
  end_time: string;
  course_code: string;
  course_title: string;
  is_lab: boolean;
  degree_code: string;
  degree_name: string;
  batch: string;
  semester: number | null;
  section_code: string;
  section_letter: string;
  is_elective: boolean;
  is_merged_slot: boolean;
  raw_text: string;
}

const DAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"];

const DEGREE_COLORS: Record<string, { bg: string; text: string; border: string; accent: string }> = {
  BBA: {
    bg: "bg-blue-50 dark:bg-blue-950/30",
    text: "text-blue-700 dark:text-blue-300",
    border: "border-blue-200 dark:border-blue-800",
    accent: "bg-blue-600",
  },
  BSBA: {
    bg: "bg-emerald-50 dark:bg-emerald-950/30",
    text: "text-emerald-700 dark:text-emerald-300",
    border: "border-emerald-200 dark:border-emerald-800",
    accent: "bg-emerald-600",
  },
  BSAF: {
    bg: "bg-purple-50 dark:bg-purple-950/30",
    text: "text-purple-700 dark:text-purple-300",
    border: "border-purple-200 dark:border-purple-800",
    accent: "bg-purple-600",
  },
  BSFT: {
    bg: "bg-amber-50 dark:bg-amber-950/30",
    text: "text-amber-700 dark:text-amber-300",
    border: "border-amber-200 dark:border-amber-800",
    accent: "bg-amber-600",
  },
};

export default function HomePage() {
  const schedule = timetableData.schedule as ScheduleItem[];
  const degreesMeta = timetableData.degrees as Record<
    string,
    { name: string; code: string; batches: string[]; sections: string[] }
  >;

  // Available degrees list
  const degreeOptions = useMemo(() => {
    return Object.keys(degreesMeta).map((key) => ({
      code: key,
      name: degreesMeta[key].name,
    }));
  }, [degreesMeta]);

  // States
  const [selectedDegree, setSelectedDegree] = useState<string>("BBA");
  const [selectedBatch, setSelectedBatch] = useState<string>("2026");
  const [selectedSection, setSelectedSection] = useState<string>("BBA01B");
  const [selectedDay, setSelectedDay] = useState<string>("Monday");

  // Dynamic Batch options based on Selected Degree
  const availableBatches = useMemo(() => {
    if (!selectedDegree || !degreesMeta[selectedDegree]) return [];
    return degreesMeta[selectedDegree].batches;
  }, [selectedDegree, degreesMeta]);

  // Dynamic Section options based on Selected Degree & Selected Batch
  const availableSections = useMemo(() => {
    if (!selectedDegree) return [];
    const secSet = new Set<string>();

    schedule.forEach((item) => {
      if (item.degree_code === selectedDegree) {
        if (!selectedBatch || item.batch === selectedBatch || item.batch === "All") {
          secSet.add(item.section_code);
        }
      }
    });

    const list = Array.from(secSet).sort();
    return list.length > 0 ? list : (degreesMeta[selectedDegree]?.sections || []);
  }, [selectedDegree, selectedBatch, schedule, degreesMeta]);

  // Handle cascading changes
  const handleDegreeChange = (degreeCode: string) => {
    setSelectedDegree(degreeCode);
    const newBatches = degreesMeta[degreeCode]?.batches || [];
    const defaultBatch = newBatches[0] || "";
    setSelectedBatch(defaultBatch);

    // Find first available section for this degree and batch
    const candidateSections = schedule
      .filter((s) => s.degree_code === degreeCode && (s.batch === defaultBatch || defaultBatch === ""))
      .map((s) => s.section_code);

    const firstSec = candidateSections[0] || degreesMeta[degreeCode]?.sections[0] || "";
    setSelectedSection(firstSec);
  };

  const handleBatchChange = (batch: string) => {
    setSelectedBatch(batch);
    const candidateSections = schedule
      .filter((s) => s.degree_code === selectedDegree && (s.batch === batch || batch === ""))
      .map((s) => s.section_code);

    if (candidateSections.length > 0 && !candidateSections.includes(selectedSection)) {
      setSelectedSection(candidateSections[0]);
    }
  };

  // Filtered schedule results
  const filteredSchedule = useMemo(() => {
    return schedule
      .filter((item) => {
        const matchesDegree = !selectedDegree || item.degree_code === selectedDegree;
        const matchesBatch = !selectedBatch || item.batch === selectedBatch || item.batch === "All";
        const matchesSection = !selectedSection || item.section_code === selectedSection || item.section_code === "ALL";
        const matchesDay = !selectedDay || item.day.toLowerCase() === selectedDay.toLowerCase();

        return matchesDegree && matchesBatch && matchesSection && matchesDay;
      })
      .sort((a, b) => a.start_time.localeCompare(b.start_time));
  }, [schedule, selectedDegree, selectedBatch, selectedSection, selectedDay]);

  // Weekly overview count
  const weeklyDayCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    DAYS.forEach((d) => {
      counts[d] = schedule.filter(
        (s) =>
          s.degree_code === selectedDegree &&
          (!selectedBatch || s.batch === selectedBatch || s.batch === "All") &&
          (!selectedSection || s.section_code === selectedSection || s.section_code === "ALL") &&
          s.day.toLowerCase() === d.toLowerCase()
      ).length;
    });
    return counts;
  }, [schedule, selectedDegree, selectedBatch, selectedSection]);

  const activeDegreeColor = DEGREE_COLORS[selectedDegree] || DEGREE_COLORS.BBA;

  return (
    <div className="min-h-screen bg-slate-50 text-slate-800 pb-20">
      {/* Top Header */}
      <header className="sticky top-0 z-30 bg-white/90 backdrop-blur-md border-b border-slate-200 shadow-sm">
        <div className="max-w-md mx-auto px-4 py-3.5 flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-blue-700 to-indigo-600 flex items-center justify-center text-white font-black text-lg shadow-md shadow-blue-500/20">
              F
            </div>
            <div>
              <h1 className="text-base font-bold text-slate-900 leading-tight">FSM Timetable</h1>
              <p className="text-xs text-slate-500 font-medium">FAST School of Management</p>
            </div>
          </div>
          <div className="flex items-center space-x-1.5 px-2.5 py-1 rounded-full bg-blue-50 border border-blue-200/60 text-blue-700 text-xs font-semibold">
            <Sparkles className="w-3.5 h-3.5 text-blue-600" />
            <span>Fall 2026</span>
          </div>
        </div>
      </header>

      {/* Main Container */}
      <main className="max-w-md mx-auto px-4 pt-4 space-y-4">
        {/* Filter Card */}
        <section className="bg-white rounded-2xl p-4 shadow-card border border-slate-200/80 space-y-3.5">
          <div className="flex items-center justify-between border-b border-slate-100 pb-2.5">
            <div className="flex items-center space-x-2 text-slate-700 font-semibold text-sm">
              <Filter className="w-4 h-4 text-blue-600" />
              <span>Select Your Cohort</span>
            </div>
            <span className="text-[11px] font-medium px-2 py-0.5 rounded-md bg-slate-100 text-slate-600">
              {filteredSchedule.length} {filteredSchedule.length === 1 ? "Class" : "Classes"} Today
            </span>
          </div>

          <div className="grid grid-cols-1 gap-3">
            {/* Degree Select */}
            <div>
              <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1.5 flex items-center gap-1.5">
                <GraduationCap className="w-3.5 h-3.5 text-slate-400" />
                Degree Program
              </label>
              <div className="relative">
                <select
                  value={selectedDegree}
                  onChange={(e) => handleDegreeChange(e.target.value)}
                  className="w-full bg-slate-50 hover:bg-slate-100/80 focus:bg-white text-slate-900 font-medium text-sm rounded-xl px-3.5 py-2.5 border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all appearance-none cursor-pointer"
                >
                  {degreeOptions.map((deg) => (
                    <option key={deg.code} value={deg.code}>
                      {deg.code} — {deg.name}
                    </option>
                  ))}
                </select>
                <div className="absolute right-3.5 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                  ▼
                </div>
              </div>
            </div>

            {/* Batch & Section 2-Column Grid */}
            <div className="grid grid-cols-2 gap-2.5">
              {/* Batch Select */}
              <div>
                <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1.5 flex items-center gap-1.5">
                  <Calendar className="w-3.5 h-3.5 text-slate-400" />
                  Batch / Year
                </label>
                <div className="relative">
                  <select
                    value={selectedBatch}
                    onChange={(e) => handleBatchChange(e.target.value)}
                    className="w-full bg-slate-50 hover:bg-slate-100/80 focus:bg-white text-slate-900 font-medium text-sm rounded-xl px-3 py-2.5 border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all appearance-none cursor-pointer"
                  >
                    {availableBatches.map((b) => (
                      <option key={b} value={b}>
                        Batch {b}
                      </option>
                    ))}
                  </select>
                  <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400 text-xs">
                    ▼
                  </div>
                </div>
              </div>

              {/* Section Select */}
              <div>
                <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1.5 flex items-center gap-1.5">
                  <Layers className="w-3.5 h-3.5 text-slate-400" />
                  Section
                </label>
                <div className="relative">
                  <select
                    value={selectedSection}
                    onChange={(e) => setSelectedSection(e.target.value)}
                    className="w-full bg-slate-50 hover:bg-slate-100/80 focus:bg-white text-slate-900 font-bold text-sm rounded-xl px-3 py-2.5 border border-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all appearance-none cursor-pointer text-blue-700"
                  >
                    {availableSections.map((sec) => (
                      <option key={sec} value={sec}>
                        {sec}
                      </option>
                    ))}
                  </select>
                  <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400 text-xs">
                    ▼
                  </div>
                </div>
              </div>
            </div>
          </div>
        </section>

        {/* Day Selector Pills (Horizontal swipeable tabs) */}
        <section className="space-y-1.5">
          <div className="flex items-center justify-between px-1">
            <span className="text-xs font-bold uppercase tracking-wider text-slate-400">Select Day</span>
            <span className="text-[11px] text-slate-500 font-medium">{selectedDay} Schedule</span>
          </div>
          <div className="flex space-x-2 overflow-x-auto pb-1 scrollbar-none">
            {DAYS.map((day) => {
              const isSelected = selectedDay.toLowerCase() === day.toLowerCase();
              const count = weeklyDayCounts[day] || 0;

              return (
                <button
                  key={day}
                  onClick={() => setSelectedDay(day)}
                  className={`flex-1 min-w-[70px] py-2 px-2 rounded-xl flex flex-col items-center justify-center transition-all ${
                    isSelected
                      ? "bg-blue-600 text-white shadow-md shadow-blue-500/25 font-bold scale-[1.02]"
                      : "bg-white text-slate-600 border border-slate-200/80 hover:bg-slate-100 font-medium"
                  }`}
                >
                  <span className="text-xs">{day.slice(0, 3)}</span>
                  <span
                    className={`text-[10px] mt-0.5 px-1.5 py-0.2 rounded-full ${
                      isSelected ? "bg-blue-500/80 text-white" : "bg-slate-100 text-slate-500"
                    }`}
                  >
                    {count} {count === 1 ? "cls" : "cls"}
                  </span>
                </button>
              );
            })}
          </div>
        </section>

        {/* Timeline Results */}
        <section className="space-y-3 pt-1">
          {filteredSchedule.length === 0 ? (
            /* Free Day Empty State */
            <div className="bg-white rounded-2xl p-8 text-center border border-slate-200 shadow-sm space-y-3">
              <div className="w-14 h-14 mx-auto rounded-full bg-emerald-50 text-emerald-600 flex items-center justify-center">
                <Coffee className="w-7 h-7" />
              </div>
              <div>
                <h3 className="text-base font-bold text-slate-800">No Classes Scheduled</h3>
                <p className="text-xs text-slate-500 mt-1 max-w-[240px] mx-auto">
                  There are no lectures or labs scheduled for <span className="font-semibold text-slate-700">{selectedSection}</span> on {selectedDay}.
                </p>
              </div>
              <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-slate-100 text-slate-600 text-xs font-medium">
                <CheckCircle2 className="w-3.5 h-3.5 text-emerald-500" />
                <span>Enjoy your free day!</span>
              </div>
            </div>
          ) : (
            /* Vertical Timeline Cards */
            <div className="relative pl-5 space-y-3.5 before:content-[''] before:absolute before:left-2 before:top-3 before:bottom-3 before:w-[2px] before:bg-slate-200">
              {filteredSchedule.map((item, idx) => {
                const isLab = item.is_lab;
                return (
                  <div key={item.id + idx} className="relative group">
                    {/* Timeline Dot */}
                    <div
                      className={`absolute -left-5 top-4 w-4 h-4 rounded-full border-2 border-white shadow-sm flex items-center justify-center transition-transform group-hover:scale-110 ${
                        isLab ? "bg-purple-600 ring-2 ring-purple-100" : "bg-blue-600 ring-2 ring-blue-100"
                      }`}
                    >
                      <div className="w-1.5 h-1.5 rounded-full bg-white" />
                    </div>

                    {/* Schedule Card */}
                    <div className="bg-white rounded-2xl p-4 border border-slate-200/90 shadow-card hover:shadow-md transition-all">
                      {/* Top Meta Bar */}
                      <div className="flex items-center justify-between gap-2 mb-2">
                        {/* Time Badge */}
                        <div className="inline-flex items-center space-x-1.5 bg-slate-100 text-slate-800 px-2.5 py-1 rounded-lg text-xs font-bold">
                          <Clock className="w-3.5 h-3.5 text-slate-500" />
                          <span>{item.time_slot}</span>
                        </div>

                        {/* Room Badge */}
                        <div className="inline-flex items-center space-x-1 bg-blue-50 text-blue-700 border border-blue-200/60 px-2.5 py-1 rounded-lg text-xs font-bold">
                          <MapPin className="w-3.5 h-3.5 text-blue-600" />
                          <span>{item.room}</span>
                        </div>
                      </div>

                      {/* Course Information */}
                      <div className="space-y-1">
                        <div className="flex items-start justify-between gap-2">
                          <h4 className="text-sm font-bold text-slate-900 leading-snug">
                            {item.course_title}
                          </h4>
                        </div>
                        <div className="flex items-center gap-2">
                          <span className="text-xs font-mono font-bold text-slate-500 bg-slate-100 px-1.5 py-0.5 rounded">
                            {item.course_code}
                          </span>
                          <span className="text-xs text-slate-400">•</span>
                          <span className="text-xs font-medium text-slate-600">{item.section_code}</span>
                        </div>
                      </div>

                      {/* Bottom Tags */}
                      <div className="flex flex-wrap items-center gap-1.5 mt-3 pt-2.5 border-t border-slate-100">
                        {isLab ? (
                          <span className="inline-flex items-center gap-1 text-[11px] font-semibold px-2 py-0.5 rounded-md bg-purple-50 text-purple-700 border border-purple-200/60">
                            <FlaskConical className="w-3 h-3" />
                            Lab Session
                          </span>
                        ) : (
                          <span className="inline-flex items-center gap-1 text-[11px] font-semibold px-2 py-0.5 rounded-md bg-blue-50 text-blue-700 border border-blue-200/60">
                            <BookOpen className="w-3 h-3" />
                            Lecture
                          </span>
                        )}

                        {item.is_merged_slot && (
                          <span className="inline-flex items-center gap-1 text-[11px] font-medium px-2 py-0.5 rounded-md bg-amber-50 text-amber-700 border border-amber-200/60">
                            Extended / Double Slot
                          </span>
                        )}

                        {item.is_elective && (
                          <span className="inline-flex items-center gap-1 text-[11px] font-medium px-2 py-0.5 rounded-md bg-emerald-50 text-emerald-700 border border-emerald-200/60">
                            Elective
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </section>

        {/* Quick Footer Info */}
        <footer className="text-center pt-6 pb-4 space-y-1 text-slate-400 text-xs">
          <p className="font-medium text-slate-500">FAST-NUCES Islamabad • School of Management</p>
          <p className="text-[11px]">Static Data Source • Auto Sync Pipeline</p>
        </footer>
      </main>
    </div>
  );
}
